// Expander — Gtk.Expander
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles expander-widget with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ExpanderProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.Expander */
  child?: ReactNode

  /** gboolean, from Gtk.Expander */
  expanded?: boolean

  /** utf8, from Gtk.Expander */
  label?: string

  /** Widget, from Gtk.Expander */
  labelWidget?: ReactNode

  /** gboolean, from Gtk.Expander */
  resizeToplevel?: boolean

  /** gboolean, from Gtk.Expander */
  useMarkup?: boolean

  /** gboolean, from Gtk.Expander */
  useUnderline?: boolean
}

export function Expander({ className, children, label }: ExpanderProps) {
  return (
    <div className={cn("duration-[300ms]", "shadow-none", className)}>
      {label}
      {children}
    </div>
  )
}
